    private static SAV6AO Open(byte[] data)=>(SAV6AO)SaveUtil.GetSaveFile(data.ToArray())!;
    private static Sb6Catalog Read(byte[] data)=>JsonSerializer.Deserialize(SaveService.ReadSecretBase6(data),SaveJsonContext.Default.Sb6Catalog)!;
    private static string Json(Sb6Edit e)=>JsonSerializer.Serialize(e,SaveJsonContext.Default.Sb6Edit);
    private static Sb6Preview Preview(byte[] data,Sb6Edit e)=>JsonSerializer.Deserialize(SaveService.PreviewSecretBase6(data,Json(e)),SaveJsonContext.Default.Sb6Preview)!;
    private static byte[] Apply(byte[] data,Sb6Edit e){var before=data.ToArray();var p=Preview(data,e);var output=SaveService.EditSecretBase6(data,Json(p.Request));Check(data.SequenceEqual(before),"SecretBase6 immutable source");Check(p.Request.TargetHash==Br4Editing.Hash(output)&&p.Result.SourceHash==p.Request.TargetHash,"SecretBase6 frozen complete target");Check(p.ChangedOffsets.SequenceEqual(Enumerable.Range(0,data.Length).Where(i=>data[i]!=output[i])),"SecretBase6 full-file change offsets");Check(SaveService.ExportWorkingCopy(output).SequenceEqual(output),"SecretBase6 complete export");return output;}
    private static byte[] Compare(byte[] data,Sb6Edit e,Action<SAV6AO> oracle){var expected=Open(data);oracle(expected);var output=Apply(data,e);Check(output.SequenceEqual(expected.Write().ToArray()),"SecretBase6 independent complete-file oracle: "+e.Action);return output;}
    private static SecretBase6 Target(SAV6AO s,int index)=>index==0?s.SecretBase.GetSecretBaseSelf():s.SecretBase.GetSecretBaseOther(index-1);
    private static SecretBase6PKM LegalPokemon(){var p=new SecretBase6PKM();p.Data.Fill(0xA6);p.Species=25;p.Form=0;p.Gender=0;p.Ability=9;p.AbilityNumber=0;p.Nature=0;p.Ball=4;p.HeldItem=0;p.Move1=p.Move2=p.Move3=p.Move4=33;p.Move1_PPUps=p.Move2_PPUps=p.Move3_PPUps=p.Move4_PPUps=3;p.IV_HP=p.IV_ATK=p.IV_DEF=p.IV_SPA=p.IV_SPE=p.IV_SPD=31;p.EV_HP=p.EV_ATK=p.EV_DEF=p.EV_SPA=p.EV_SPE=p.EV_SPD=252;p.CurrentLevel=255;p.CurrentFriendship=255;return p;}
    public static void Run()
