            var data=s.Write().ToArray();var original=data.ToArray();var c=Read(data);
            Check(c.CanEdit&&c.Bases.Length==31&&c.Stock.Length==200&&c.Bases[0].Pokemon.Length==0&&c.Bases.Skip(1).All(x=>x.Pokemon.Length==3&&x.Placements.Length==28),"SecretBase6 full physical catalog");
            for(int i=0;i<31;i++){var b=Target(Open(data),i);var publicWritable=b.GetType().GetProperties(BindingFlags.Public|BindingFlags.Instance).Where(p=>p.CanRead&&p.CanWrite).Select(p=>p.Name).Order().ToArray();Check(publicWritable.SequenceEqual(c.Bases[i].Properties.Select(x=>x.Id).Order()),"SecretBase6 complete source PropertyGrid coverage");}
            var scalarValues=new Dictionary<string,string>{["IsNew"]="1",["BaseLocation"]="86",["BoppoyamaScore"]="0xFF",["TrainerName"]="ABCDEFGHIJKLMNOP",["TeamName"]="ABCDEFGHIJKLMNOPQRST",["TeamSlogan"]="Slogan",["SayHappy"]="Happy",["SayEncourage"]="Encourage",["SayBlackboard"]="Board",["SayConfettiBall"]="Confetti",["Rank"]="Gold",["TotalFlagsFromFriends"]="0xFFFFFFFF",["TotalFlagsFromOther"]="4294967295",["CollectedFlagsToday"]="255",["CollectedFlagsYesterday"]="0"};
            for(int i=0;i<31;i++){var fields=scalarValues.Select(v=>new Sb6Value(v.Key,v.Value)).ToList();if(i>0){fields.Add(new("Language","255"));fields.Add(new("Gender","255"));}int index=i;Compare(data,new("property",c.SourceHash,i,Fields:fields.ToArray()),x=>{var b=Target(x,index);foreach(var f in fields){var p=b.GetType().GetProperty(f.Id)!;object? value=p.PropertyType==typeof(bool)?f.Value=="1":TypeDescriptor.GetConverter(p.PropertyType).ConvertFromInvariantString(f.Value!);p.SetValue(b,value);}});}
            foreach(int value in new[]{int.MinValue,-1,0,1,2,85,86,int.MaxValue})Compare(data,new("property",c.SourceHash,0,Fields:[new("BaseLocation",value.ToString())]),x=>Target(x,0).BaseLocation=value);
            for(int i=0;i<31;i++)for(int j=0;j<28;j++){int index=i,slot=j;Compare(data,new("placement",c.SourceHash,i,j,Fields:[new("Good","-1"),new("X","65535"),new("Y","0"),new("Rotation","255")]),x=>{var b=Target(x,index);var span=b.Data.Slice(4+slot*12,12);BinaryPrimitives.WriteUInt16LittleEndian(span,65535);BinaryPrimitives.WriteUInt16LittleEndian(span[2..],65535);BinaryPrimitives.WriteUInt16LittleEndian(span[4..],0);span[6]=255;});}
            for(int i=1;i<31;i++)for(int j=0;j<3;j++){int index=i,member=j;Compare(data,new("member",c.SourceHash,i,Member:j,Fields:[new("Ec","x12!AB"),new("IV_HP","99"),new("EV_HP","999"),new("PP1","0"),new("Level","0"),new("Friendship","0"),new("Shiny","0")]),x=>{var o=(SecretBase6Other)Target(x,index);var p=o.GetParticipant(member);BinaryPrimitives.WriteUInt32LittleEndian(p.Data,0x12AB);p.Data[0x28]=3;p.Data[0x16]=252;p.Data[0x24]=0;p.Data[0x30]=0;p.Data[0x2E]=0;p.Data[0x2D]&=0xDF;o.SetParticipant(member,p);});}
